function Abort([string]$Message) {
  throw "ABORTED: $Message"
}

function Repo-Path([string]$RelativePath) {
  $native = $RelativePath.Replace('/', [IO.Path]::DirectorySeparatorChar)
  return Join-Path $script:RepoRoot $native
}

function Hash-Of([string]$Path) {
  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
    Abort "Required file is missing: $Path"
  }
  return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Assert-Hash([string]$RelativePath, [string]$ExpectedHash) {
  $actual = Hash-Of (Repo-Path $RelativePath)
  if ($actual -ne $ExpectedHash.ToLowerInvariant()) {
    Abort "Checksum drift: $RelativePath`nExpected: $ExpectedHash`nActual:   $actual"
  }
}

function Git-Lines([string[]]$Arguments) {
  $output = @(& git -C $script:RepoRoot @Arguments 2>&1)
  if ($LASTEXITCODE -ne 0) {
    Abort "git $($Arguments -join ' ') failed:`n$($output -join [Environment]::NewLine)"
  }
  return @($output | ForEach-Object { [string]$_ })
}

function Git-Text([string[]]$Arguments) {
  return ((Git-Lines $Arguments) -join "`n").Trim()
}

function Migration-Count {
  if (-not (Test-Path -LiteralPath (Repo-Path "drizzle") -PathType Container)) {
    Abort "drizzle directory is missing."
  }
  return @(
    Get-ChildItem -LiteralPath (Repo-Path "drizzle") -Directory |
      Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName "migration.sql") -PathType Leaf }
  ).Count
}

function Resolve-ScannerTrustPaths {
  Write-Host "==> Re-proving locked Scanner trust-path hashes"
  $tracked = Git-Lines @("ls-files")
  $scannerMatches = New-Object System.Collections.Generic.List[string]
  $cssMatches = New-Object System.Collections.Generic.List[string]

  # Scanner-named paths first, then the rest only if necessary. Continue through
  # all tracked paths once a hash class is unresolved so path names are never assumed.
  $ordered = @($tracked | Sort-Object { if ($_ -match '(?i)scanner') { 0 } else { 1 } })
  foreach ($relative in $ordered) {
    if ([string]::IsNullOrWhiteSpace($relative)) { continue }
    $path = Repo-Path $relative
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { continue }
    try {
      $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()
    } catch {
      continue
    }
    if ($hash -eq $ScannerHash) { $scannerMatches.Add($relative) }
    if ($hash -eq $ScannerCssHash) { $cssMatches.Add($relative) }
  }

  if ($scannerMatches.Count -ne 1) {
    Abort "Locked Scanner source hash resolved to $($scannerMatches.Count) tracked files; expected exactly 1."
  }
  if ($cssMatches.Count -ne 1) {
    Abort "Locked Scanner CSS hash resolved to $($cssMatches.Count) tracked files; expected exactly 1."
  }

  $targetPaths = @($PayloadManifest.Keys)
  if ($targetPaths -contains $scannerMatches[0] -or $targetPaths -contains $cssMatches[0]) {
    Abort "Pass A payload overlaps the locked Scanner trust path."
  }

  return @{
    Scanner = $scannerMatches[0]
    ScannerCss = $cssMatches[0]
  }
}

function Preflight {
  Write-Host "CASA School - Pass A Guarded Implementation V1R1"
  Write-Host "Source-only installation; migrations are added but NEVER applied."
  Write-Host "No DB, AWS, Scanner, Staging, or Production mutation."
  Write-Host ""
  Write-Host "==> Validating repository authority and exact-source state"

  if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Abort "git is not available."
  }
  if (-not (Get-Command npm -ErrorAction SilentlyContinue)) {
    Abort "npm is not available."
  }

  $resolved = (Resolve-Path -LiteralPath $script:RepoRoot).Path
  $top = (Git-Text @("rev-parse", "--show-toplevel"))
  $topResolved = (Resolve-Path -LiteralPath $top).Path
  if ($resolved.TrimEnd([char[]]"\/") -ne $topResolved.TrimEnd([char[]]"\/")) {
    Abort "RepoRoot is not the repository root. Expected $topResolved, got $resolved"
  }
  $script:RepoRoot = $topResolved

  $branch = Git-Text @("branch", "--show-current")
  if ($branch -ne $ExpectedBranch) {
    Abort "Expected branch $ExpectedBranch, found $branch."
  }

  $head = Git-Text @("rev-parse", "--short=7", "HEAD")
  if ($head -ne $ExpectedHead) {
    Abort "Expected HEAD $ExpectedHead, found $head."
  }

  [void](Git-Lines @("merge-base", "--is-ancestor", $RequiredAncestor, "HEAD"))

  $trackedDrift = @(Git-Lines @("diff", "--name-only", "HEAD", "--") | Where-Object { $_ })
  if ($trackedDrift.Count -ne 1 -or $trackedDrift[0] -ne $AllowedTrackedDrift) {
    Abort "Tracked worktree drift is not the exact handoff state. Allowed only: $AllowedTrackedDrift`nFound:`n$($trackedDrift -join [Environment]::NewLine)"
  }
  Assert-Hash $AllowedTrackedDrift $ExpectedOnboardingHash

  Write-Host "  branch: $branch"
  Write-Host "  HEAD: $head"
  Write-Host "  allowed onboarding drift: exact hash verified"

  Write-Host ""
  Write-Host "==> Re-proving all 28 existing migration SQL artifacts"
  $count = Migration-Count
  if ($count -ne $ExpectedMigrationCountBefore) {
    Abort "Expected $ExpectedMigrationCountBefore migrations before Pass A, found $count."
  }
  foreach ($relative in ($MigrationManifest.Keys | Sort-Object)) {
    Assert-Hash $relative ([string]$MigrationManifest[$relative])
  }
  Assert-Hash $LatestMigration $LatestMigrationHash
  Assert-Hash $LatestSnapshot $LatestSnapshotHash
  Write-Host "  migrations 1-28: exact hashes verified"
  Write-Host "  latest migration + snapshot: verified"

  Write-Host ""
  Write-Host "==> Validating every Pass A source preimage"
  foreach ($relative in ($BaselineManifest.Keys | Sort-Object)) {
    Assert-Hash $relative ([string]$BaselineManifest[$relative])
  }
  foreach ($relative in $NewPaths) {
    $path = Repo-Path ([string]$relative)
    if (Test-Path -LiteralPath $path) {
      Abort "New Pass A path already exists: $relative"
    }
  }
  Write-Host "  modified preimages: $($BaselineManifest.Count) exact hashes verified"
  Write-Host "  new paths: $($NewPaths.Count) confirmed absent"

  $script:ScannerPaths = Resolve-ScannerTrustPaths
  Write-Host "  Scanner source: $($script:ScannerPaths.Scanner)"
  Write-Host "  Scanner CSS:    $($script:ScannerPaths.ScannerCss)"
  Write-Host "  Scanner trust hashes: verified"

  return @{
    Branch = $branch
    Head = $head
    Scanner = $script:ScannerPaths.Scanner
    ScannerCss = $script:ScannerPaths.ScannerCss
  }
}

function Restore-Backup([string]$BackupRoot) {
  Write-Host ""
  Write-Host "==> Rolling back Pass A source writes"
  foreach ($relative in $BaselineManifest.Keys) {
    $backup = Join-Path $BackupRoot ($relative.Replace('/', [IO.Path]::DirectorySeparatorChar))
    $target = Repo-Path $relative
    if (Test-Path -LiteralPath $backup -PathType Leaf) {
      $parent = Split-Path -Parent $target
      if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
      Copy-Item -LiteralPath $backup -Destination $target -Force
    }
  }
  foreach ($relative in $NewPaths) {
    $target = Repo-Path ([string]$relative)
    if (Test-Path -LiteralPath $target -PathType Leaf) {
      Remove-Item -LiteralPath $target -Force
    }
  }
  Write-Host "  tracked source preimages restored"
  Write-Host "  newly-added Pass A files removed"
}

$authority = Preflight
if ($PreflightOnly) {
  Write-Host ""
  Write-Host "PREFLIGHT PASSED. No files were written."
  exit 0
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Repo-Path ".casa-backups/pass-a-$stamp"
$tempRoot = Join-Path ([IO.Path]::GetTempPath()) "casa-pass-a-$stamp-$PID"
$payloadZip = Join-Path $tempRoot "payload.zip"
$payloadExtract = Join-Path $tempRoot "payload"
$writesStarted = $false

try {
  Write-Host ""
  Write-Host "==> Creating guarded backup"
  New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null
  foreach ($relative in $BaselineManifest.Keys) {
    $source = Repo-Path $relative
    $backup = Join-Path $backupRoot ($relative.Replace('/', [IO.Path]::DirectorySeparatorChar))
    $parent = Split-Path -Parent $backup
    if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    Copy-Item -LiteralPath $source -Destination $backup -Force
  }
  $metadata = [ordered]@{
    createdAt = (Get-Date).ToString("o")
    branch = $authority.Branch
    head = $authority.Head
    scannerPath = $authority.Scanner
    scannerCssPath = $authority.ScannerCss
    sourceWritesOnly = $true
    migrationsApplied = $false
  } | ConvertTo-Json -Depth 4
  Set-Content -LiteralPath (Join-Path $backupRoot "PASS_A_BACKUP_METADATA.json") -Value $metadata -Encoding UTF8
  Write-Host "  backup: $backupRoot"

  Write-Host ""
  Write-Host "==> Expanding and validating embedded Pass A payload"
  New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
  [IO.File]::WriteAllBytes($payloadZip, [Convert]::FromBase64String($PayloadBase64))
  Expand-Archive -LiteralPath $payloadZip -DestinationPath $payloadExtract -Force
  foreach ($relative in $PayloadManifest.Keys) {
    $payloadPath = Join-Path $payloadExtract ($relative.Replace('/', [IO.Path]::DirectorySeparatorChar))
    $actual = Hash-Of $payloadPath
    $expected = ([string]$PayloadManifest[$relative]).ToLowerInvariant()
    if ($actual -ne $expected) {
      Abort "Embedded payload checksum failure: $relative"
    }
  }
  Write-Host "  payload files: $($PayloadManifest.Count) hashes verified"

  Write-Host ""
  Write-Host "==> Installing Pass A source + additive migration artifacts"
  $writesStarted = $true
  foreach ($relative in ($PayloadManifest.Keys | Sort-Object)) {
    $source = Join-Path $payloadExtract ($relative.Replace('/', [IO.Path]::DirectorySeparatorChar))
    $target = Repo-Path $relative
    $parent = Split-Path -Parent $target
    if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    Copy-Item -LiteralPath $source -Destination $target -Force
  }

  Write-Host ""
  Write-Host "==> Verifying installed source"
  foreach ($relative in $PayloadManifest.Keys) {
    Assert-Hash $relative ([string]$PayloadManifest[$relative])
  }
  $afterCount = Migration-Count
  if ($afterCount -ne $ExpectedMigrationCountAfter) {
    Abort "Expected $ExpectedMigrationCountAfter migration files after Pass A, found $afterCount."
  }
  Assert-Hash $script:ScannerPaths.Scanner $ScannerHash
  Assert-Hash $script:ScannerPaths.ScannerCss $ScannerCssHash
  Write-Host "  installed payload hashes: verified"
  Write-Host "  migration source count: $afterCount (files only; NOT applied)"
  Write-Host "  Scanner trust hashes: unchanged"

  $diffCheck = @(& git -C $script:RepoRoot diff --check HEAD -- 2>&1)
  if ($LASTEXITCODE -ne 0) {
    Abort "git diff --check failed:`n$($diffCheck -join [Environment]::NewLine)"
  }
  Write-Host "  git diff --check: passed"

  Write-Host ""
  Write-Host "==> Running guarded source verification"
  & npm run typecheck
  if ($LASTEXITCODE -ne 0) { Abort "npm run typecheck failed." }

  & npm run scanner:selftest
  if ($LASTEXITCODE -ne 0) { Abort "npm run scanner:selftest failed." }

  & npm run card:selftest
  if ($LASTEXITCODE -ne 0) { Abort "npm run card:selftest failed." }

  & npm exec -- tsx scripts/pass-a-selftest.ts
  if ($LASTEXITCODE -ne 0) { Abort "Pass A source contract self-test failed." }

  Assert-Hash $script:ScannerPaths.Scanner $ScannerHash
  Assert-Hash $script:ScannerPaths.ScannerCss $ScannerCssHash

  Write-Host ""
  Write-Host "PASS A SOURCE INSTALLATION PASSED."
  Write-Host "  checkpoint authority: main/a7aa668 + exact onboarding drift"
  Write-Host "  source migrations present: 30"
  Write-Host "  migrations applied: NO"
  Write-Host "  database mutation: NO"
  Write-Host "  AWS mutation: NO"
  Write-Host "  Scanner mutation: NO"
  Write-Host "  Staging/Production mutation: NO"
  Write-Host "  backup: $backupRoot"
  Write-Host ""
  Write-Host "Next verification (do not migrate yet):"
  Write-Host "  npm run build"
  Write-Host "  git status --short"
  Write-Host "Paste that output back into ChatGPT to continue the guarded Pass A rollout."
}
catch {
  if ($writesStarted -and (Test-Path -LiteralPath $backupRoot -PathType Container)) {
    try { Restore-Backup $backupRoot } catch { Write-Warning "Automatic rollback encountered an error: $($_.Exception.Message)" }
  }
  Write-Error $_.Exception.Message
  exit 1
}
finally {
  if (Test-Path -LiteralPath $tempRoot -PathType Container) {
    Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
  }
}
